WITH with_windows AS (SELECT *, RANK() OVER (PARTITION BY txn_type, account_id ORDER BY amount DESC) AS amount_rank, FIRST_VALUE(merchant) IGNORE NULLS OVER (PARTITION BY account_id ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_merchant, NTILE(10) OVER (PARTITION BY account_id ORDER BY amount, id) AS amount_bucket, SUM(amount) OVER (PARTITION BY merchant ORDER BY CAST(txn_time AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS amount_sum_30d FROM transactions) SELECT id, txn_type, amount, first_known_merchant, amount_bucket, CASE WHEN txn_type RLIKE '^(REFUND|FEE)$' THEN 'PRIORITY' ELSE 'GROUP_A' END AS txn_type_zone FROM with_windows;
